 private Map<String,Object>read(String authorization,String run,String generation,String sourceId,long offset)throws Exception{if(stopped)throw new IOException("PHONE_OBSERVER_STOPPED");long readEpoch=epoch;String secret=source.capability();if(secret==null||!secret.matches("[a-f0-9]{64}")||authorization==null||!MessageDigest.isEqual(("Bearer "+secret).getBytes(StandardCharsets.US_ASCII),authorization.getBytes(StandardCharsets.US_ASCII)))throw new IOException("PHONE_OBSERVER_CAPABILITY");Prefix p=source.prefix();if(!p.run.equals(run)||!p.generation.equals(generation)||!p.source.equals(sourceId)||offset<0||offset>p.bytes||Files.isSymbolicLink(p.file.toPath()))throw new IOException("PHONE_OBSERVER_CONTEXT_OR_OFFSET");int length=(int)Math.min(65536,p.bytes-offset);byte[]bytes=new byte[length];try(RandomAccessFile in=new RandomAccessFile(p.file,"r")){in.seek(offset);in.readFully(bytes);}Prefix after=source.prefix();if(stopped||readEpoch!=epoch||!p.run.equals(after.run)||!p.generation.equals(after.generation)||!p.source.equals(after.source)||!Objects.equals(secret,source.capability()))throw new IOException("PHONE_OBSERVER_REVOKED_DURING_READ");return Data97.m("ok",true,"format","aeris-phone06-wal-prefix","run",p.run,"generation",p.generation,"sourceId",p.source,"offset",offset,"nextOffset",offset+bytes.length,"committedBytes",p.bytes,"committedRecords",p.records,"committedHead",p.head,"committedClosed",false,"nativeElapsedMs",source.now(),"dataBase64",Base64.getEncoder().encodeToString(bytes),"scope","READ_ONLY_COMMITTED_NATIVE_WAL_NOT_AUTHORITY");}
