 public synchronized Map<String,Object>start()throws Exception{if(!stopped||worker!=null&&worker.isAlive())throw new IOException("PHONE_OBSERVER_PREVIOUS_WORKER_ACTIVE_OR_STARTED");Prefix p=source.prefix();if(source.capability()==null)throw new IOException("PHONE_OBSERVER_ADMISSION_CAPABILITY_REQUIRED");ServerSocket ready=new ServerSocket();ready.bind(new InetSocketAddress("127.0.0.1",5967),1);ready.setSoTimeout(200);server=ready;epoch++;stopped=false;worker=new Thread(()->serve(ready),"phone06-read-only-wal");worker.start();return Data97.m("ok",true,"listening",true,"port",5967,"run",p.run,"generation",p.generation,"sourceId",p.source,"capabilityInResponse",false,"commands",false);}
 private void serve(ServerSocket ready){try{while(!stopped){try{source.prefix();}catch(Exception e){break;}Socket connection;try{connection=ready.accept();}catch(SocketTimeoutException e){continue;}active=connection;try(Socket s=connection){if(stopped)throw new IOException("PHONE_OBSERVER_STOPPED");ScheduledFuture<?>end=deadline.schedule(()->{try{s.close();}catch(Exception ignored){}},1000,TimeUnit.MILLISECONDS);try{s.setSoTimeout(500);long n=source.now();if(lastRequest>=0&&n-lastRequest<100)throw new IOException("PHONE_OBSERVER_REQUEST_RATE");lastRequest=n;ByteArrayOutputStream raw=new ByteArrayOutputStream();InputStream in=s.getInputStream();int current=0;while(current!=0x0d0a0d0a){int b=in.read();if(b<0||b>127||raw.size()>=4096)throw new IOException("PHONE_OBSERVER_HEADER_BOUND");raw.write(b);current=current<<8|b;}String[]lines=new String(raw.toByteArray(),StandardCharsets.US_ASCII).split("\r\n");if(!lines[0].equals("GET /wal06 HTTP/1.1"))throw new IOException("PHONE_OBSERVER_READ_ONLY_ROUTE");Map<String,String>h=new HashMap<>();for(int i=1;i<lines.length;i++){int at=lines[i].indexOf(':');if(at<1)throw new IOException("PHONE_OBSERVER_HEADER");String k=lines[i].substring(0,at).toLowerCase(Locale.ROOT);if(h.put(k,lines[i].substring(at+1).trim())!=null)throw new IOException("PHONE_OBSERVER_DUPLICATE_HEADER");}if(!"127.0.0.1:5967".equals(h.get("host"))||h.containsKey("content-length")||h.containsKey("transfer-encoding")||h.size()>16)throw new IOException("PHONE_OBSERVER_HEADER_PROFILE");String offset=h.get("x-offset");if(offset==null||!offset.matches("0|[1-9][0-9]{0,9}"))throw new IOException("PHONE_OBSERVER_OFFSET");byte[]body=Data97.json(read(h.get("authorization"),h.get("x-run"),h.get("x-generation"),h.get("x-source-id"),Long.parseLong(offset))).getBytes(StandardCharsets.UTF_8);if(total+body.length>64L*1024*1024)throw new IOException("PHONE_OBSERVER_TOTAL_BOUND");Prefix currentPrefix=source.prefix();if(stopped||!Objects.equals(h.get("authorization"),"Bearer "+source.capability())||!Objects.equals(h.get("x-run"),currentPrefix.run)||!Objects.equals(h.get("x-generation"),currentPrefix.generation)||!Objects.equals(h.get("x-source-id"),currentPrefix.source))throw new IOException("PHONE_OBSERVER_REVOKED_BEFORE_OUTPUT");total+=body.length;OutputStream out=s.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nCache-Control: no-store\r\nConnection: close\r\nContent-Length: "+body.length+"\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(body);out.flush();}finally{end.cancel(false);active=null;}}catch(Exception refused){/* Capabilities/headers are deliberately never logged or reflected. */}}}catch(Exception ignored){}finally{synchronized(this){if(server==ready)close();else try{ready.close();}catch(Exception ignored){}}}}
